  ('digital-citizenship', 'Digital Citizenship', 'Respectful, responsible and safe behaviour online.', 'people', '#A78BFA', true, 3),
  ('ai-ethics', 'Artificial Intelligence Ethics', 'Bias, transparency and accountability in AI systems.', 'hardware-chip', '#F472B6', true, 4),
  ('academic-integrity', 'Academic Integrity', 'Honesty in schoolwork, exams and research.', 'school', '#60A5FA', true, 5),
  ('social-media', 'Social Media Ethics', 'Sharing, misinformation, consent and online reputation.', 'chatbubbles', '#FB923C', true, 6),
  ('professional-ethics', 'Professional Ethics', 'Duties of IT professionals to employers, clients and the public.', 'briefcase', '#34D399', true, 7),
  ('software-development', 'Software Development Ethics', 'Quality, honesty and harm prevention when building software.', 'code-slash', '#22D3EE', true, 8),
  ('accessibility', 'Digital Accessibility', 'Designing technology that everyone can use.', 'accessibility', '#C084FC', true, 9),
  ('environmental', 'Environmental Ethics', 'E-waste, energy use and sustainable computing.', 'leaf', '#4ADE80', true, 10),
